import java.util.*;

public class Ex10ConditionsReport {
    record Eval(String name, boolean matched, String reason) {}

    public static void main(String[] args) {
        List<Eval> evals = List.of(
                new Eval("DataSourceAutoConfiguration", true,
                        "@ConditionalOnClass found com.zaxxer.hikari.HikariDataSource"),
                new Eval("DataSourceAutoConfiguration$PooledDataSource", false,
                        "@ConditionalOnMissingBean found user-defined dataSource"),
                new Eval("RedisAutoConfiguration", false,
                        "@ConditionalOnClass did not find org.springframework.data.redis.core.RedisOperations"),
                new Eval("WebMvcAutoConfiguration", true,
                        "@ConditionalOnWebApplication (SERVLET)"),
                new Eval("SecurityAutoConfiguration", false,
                        "excluded by @SpringBootApplication(exclude = ...)"));

        System.out.println("CONDITIONS EVALUATION REPORT");
        System.out.println("Positive matches:");
        for (Eval e : evals) if (e.matched()) System.out.println("  + " + e.name() + "  [" + e.reason() + "]");
        System.out.println("Negative matches:");
        for (Eval e : evals) if (!e.matched()) System.out.println("  - " + e.name() + "  [" + e.reason() + "]");

        long pos = 0;
        for (Eval e : evals) if (e.matched()) pos++;
        System.out.println("summary: positive=" + pos + " negative=" + (evals.size() - pos));
    }
}
